#!/usr/bin/env bash
set -euo pipefail
export AWS_PAGER=""

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

ROLE_NAME='ec2-ops'

# Trust policy: who can assume the role
cat > trust.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
ROLECRAFT_EOF

# Permissions policy
cat > policy.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "Ec2StartStopView",
      "Effect": "Allow",
      "Action": [
        "ec2:DescribeAvailabilityZones",
        "ec2:DescribeInstanceStatus",
        "ec2:DescribeInstanceTypes",
        "ec2:DescribeInstances",
        "ec2:DescribeTags",
        "ec2:DescribeVolumes"
      ],
      "Resource": "*"
    },
    {
      "Sid": "Ec2StartStopManage",
      "Effect": "Allow",
      "Action": [
        "ec2:StartInstances",
        "ec2:StopInstances"
      ],
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringEquals": {
          "aws:ResourceTag/Env": "dev"
        }
      }
    }
  ]
}
ROLECRAFT_EOF

aws iam create-role --role-name="$ROLE_NAME" --assume-role-policy-document file://trust.json --description 'Created with RoleCraft' >/dev/null
POLICY_ARN=$(aws iam create-policy --policy-name="${ROLE_NAME}-policy" --policy-document file://policy.json --query Policy.Arn --output text)
aws iam attach-role-policy --role-name="$ROLE_NAME" --policy-arn="$POLICY_ARN"
aws iam attach-role-policy --role-name="$ROLE_NAME" --policy-arn 'arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore'

# EC2 instances use roles through an instance profile.
aws iam create-instance-profile --instance-profile-name="$ROLE_NAME" >/dev/null
aws iam add-role-to-instance-profile --instance-profile-name="$ROLE_NAME" --role-name="$ROLE_NAME"

echo "Created role $ROLE_NAME."
echo "Created instance profile $ROLE_NAME."
echo "Created and attached policy ${ROLE_NAME}-policy."
